func TestHealthPage(t *testing.T) {
	env := newTestEnv(t)
	body := env.do(ingressGET("/health")).Body.String()
	if !strings.Contains(body, "Noch keine Gesundheitsdaten") || !strings.Contains(body, `href="health" aria-current="page"`) {
		t.Fatal("empty state with active tab expected")
	}
	ctx := context.Background()
	// testNow is 3 May 2026; resting HR is current, the training status is old.
	for date, v := range map[string]store.HealthValues{
		"2026-05-02": {"resting_hr": 51, "hrv_night_avg": 62.0, "hrv_baseline_low": 55.0, "hrv_baseline_high": 70.0,
			"hrv_status": "IN_RANGE", "sleep_s": 27000, "sleep_score": 84, "steps": 12345, "intensity_moderate_min": 10, "intensity_vigorous_min": 20},
		"2026-04-30": {"resting_hr": 53, "weight_kg": 78.5, "vo2max_cycling": 51.0},
		"2026-04-01": {"training_status": "PRODUCTIVE", "readiness_score": 70, "readiness_level": "HIGH"},
	} {
		if err := env.store.UpsertHealth(ctx, date, v); err != nil {
			t.Fatal(err)
		}
	}
	body = env.do(ingressGET("/health")).Body.String()
	for _, want := range []string{
		"<strong>51 bpm</strong>", "<strong>62 ms</strong>", "im Normalbereich · Basis 55–70 ms", "<strong>7:30</strong>",
		"Schlafwert 84", "<strong>12.345</strong>", "<strong>78,5 kg</strong>", "Stand 30.04.2026", "<strong>Produktiv</strong>",
		"Stand 01.04.2026", `from "./static/health.js?v=`, `"id":"rhr"`, `"sleep_h":[null,null,7.5]`, `"intensity_min":[null,null,50]`,
	} {
		if !strings.Contains(body, want) {
			t.Errorf("health page missing %q", want)
		}
	}
	// 90 days include 1 April; 30 days do not.
	if body := env.do(ingressGET("/health?range=30")).Body.String(); strings.Contains(body, `"id":"readiness"`) {
		t.Error("readiness of 1 April is outside 30 days")
	}
	if !strings.Contains(body, `"id":"readiness"`) {
		t.Error("readiness chart within 90 days")
	}
	if m := absoluteURL.FindString(strings.Replace(body, `<base href="/api/hassio_ingress/tok3n/">`, "", 1)); m != "" {
		t.Errorf("absolute URL %q", m)
	}
	// The heatmap moved to "Mehr".
	if body := env.do(ingressGET("/heatmap")).Body.String(); !strings.Contains(body, `href="more" aria-current="page"`) {
		t.Error("heatmap belongs to the Mehr tab")
	}
}

